const categories = {'all':'ข่าวทั้งหมด','industrial-robots':'หุ่นยนต์อุตสาหกรรม','humanoids':'หุ่นยนต์ฮิวแมนนอยด์','ai-automation':'AI และระบบอัตโนมัติ','research':'งานวิจัย','drones':'โดรน','industry-news':'ข่าววงการ'};
const articles = window.ROBOT_NEWS_ARTICLES;
const $=s=>document.querySelector(s), params=new URLSearchParams(location.search);
let category=categories[params.get('category')]?params.get('category'):'industrial-robots', page=1;
const perPage=6, esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=d=>new Date(d+'T12:00:00').toLocaleDateString('th-TH',{day:'numeric',month:'short',year:'numeric'});
$('#source').innerHTML += [...new Set(articles.map(a=>a.source))].sort().map(s=>`<option>${esc(s)}</option>`).join('');
function setCategory(c){category=c;page=1;const u=new URL(location);u.searchParams.set('category',c);history.replaceState(null,'',u);render()}
function filtered(){const q=$('#search').value.trim().toLocaleLowerCase();return articles.filter(a=>(category==='all'||a.category===category)&&(!$('#source').value||a.source===$('#source').value)&&(`${a.title} ${a.summary} ${a.source}`.toLocaleLowerCase().includes(q))).sort((a,b)=>$('#sort').value==='old'?a.date.localeCompare(b.date):b.date.localeCompare(a.date))}
function render(){
$('#categories').innerHTML=Object.entries(categories).map(([key,label])=>`<button data-category="${key}" class="${category===key?'active':''}" aria-pressed="${category===key}">${label}</button>`).join('');
const results=filtered(), total=Math.ceil(results.length/perPage); page=Math.max(1,Math.min(page,total||1));
$('#section-title').textContent=categories[category];$('#count').textContent=`${results.length} บทความ`;
$('#grid').innerHTML=results.length?results.slice((page-1)*perPage,page*perPage).map(a=>`<article class="card"><button class="image-button" data-open="${a.id}" aria-label="อ่าน ${esc(a.title)}">${a.image?`<img src="${esc(a.image)}" alt="${esc(a.title)}" loading="lazy">`:`<span class="image-fallback">${esc(a.source)}</span>`}</button><div class="card-body"><div class="tag-row"><span class="tag">${categories[a.category]}</span><span class="fresh">สรุปภาษาไทย</span></div><h3><button class="headline" data-open="${a.id}">${esc(a.title)}</button></h3><p class="summary">${esc(a.summary)}</p><div class="metadata"><a class="source-link" href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">${esc(a.source)}</a><time datetime="${a.date}">${date(a.date)}</time></div><div class="card-bottom"><button class="read-more" data-open="${a.id}">อ่านข่าวฉบับละเอียด <span aria-hidden="true">↗</span></button><button class="copy" data-copy="${a.id}" aria-label="คัดลอกลิงก์ข่าว ${esc(a.title)}">คัดลอกลิงก์ ⧉</button></div></div></article>`).join(''):`<div class="empty"><h3>ไม่พบข่าวที่ตรงกับการค้นหา</h3><p>ลองใช้คำค้นอื่น หรือเลือกแหล่งข่าวและหมวดหมู่ใหม่</p><button id="reset">ล้างตัวกรอง</button></div>`;
$('#pagination').innerHTML=total>1?`<button data-page="${page-1}" ${page===1?'disabled':''}>← ก่อนหน้า</button>${Array.from({length:total},(_,i)=>`<button data-page="${i+1}" class="${page===i+1?'active':''}" ${page===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')}<button data-page="${page+1}" ${page===total?'disabled':''}>ถัดไป →</button>`:'';
document.querySelectorAll('.image-button img').forEach(img=>img.addEventListener('error',()=>{const a=articles.find(a=>a.id===img.parentElement.dataset.open);img.parentElement.innerHTML=`<span class="image-fallback">${esc(a.source)}</span>`},{once:true}));
}
function openArticle(id){if(articles.some(a=>a.id===id))location.assign('/articles/'+encodeURIComponent(id)+'.html')}
function info(html){$('#dialog-content').innerHTML=html;$('#dialog').showModal()}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.category)setCategory(b.dataset.category);if(b.dataset.open)openArticle(b.dataset.open);if(b.dataset.page){page=Number(b.dataset.page);render();$('#news').scrollIntoView({behavior:'smooth',block:'start'})}if(b.id==='reset'){$('#search').value='';$('#source').value='';setCategory('all')}if(b.dataset.copy){const u=new URL('/articles/'+encodeURIComponent(b.dataset.copy)+'.html',location.origin);try{await navigator.clipboard.writeText(u.href);$('#toast').textContent='คัดลอกลิงก์ข่าวแล้ว';$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2400)}catch{info(`<h2>ลิงก์ข่าว</h2><p>เลือกและคัดลอกลิงก์ด้านล่าง</p><input aria-label="ลิงก์ข่าว" readonly value="${esc(u.href)}">`)}}});
['search','source','sort'].forEach(id=>$('#'+id).addEventListener(id==='search'?'input':'change',()=>{page=1;render()}));
$('#close-dialog').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#sources-button').onclick=()=>info(`<h2>แหล่งข่าวของเรา</h2><p>ชุดข่าวนี้รวบรวมและสรุปจาก ${new Set(articles.map(a=>a.source)).size} แหล่ง ทุกข่าวมีลิงก์กลับไปยังบทความต้นฉบับ</p><ul>${[...new Set(articles.map(a=>a.source))].map(s=>`<li><a href="${new URL(articles.find(a=>a.source===s).url).origin}" target="_blank" rel="noopener noreferrer">${esc(s)} ↗</a></li>`).join('')}</ul>`);
$('#about-button').onclick=()=>info('<h2>เรื่องหุ่นยนต์ ที่อ่านรู้เรื่อง</h2><p>หุ่นยนต์ครับ รวบรวมข่าวหุ่นยนต์และระบบอัตโนมัติจากทั่วโลก แล้วสรุปเป็นภาษาไทยเพื่อให้ติดตามเทคโนโลยีได้ง่ายขึ้น</p><p>คัดข่าวจากหลายแหล่ง ตรวจสอบข้อมูลและเรียบเรียงสรุปภาษาไทย พร้อมภาพ วิดีโอ และลิงก์ต้นฉบับ</p><p>โครงสร้างได้รับแรงบันดาลใจจาก Robot News เว็บไซต์นี้เป็นต้นแบบแยกต่างหาก ไม่ใช่เว็บไซต์ทางการของ Robot News</p>');
try{if(localStorage.getItem('robot-theme')==='dark')document.body.classList.add('dark')}catch{}
$('#theme').onclick=()=>{const dark=document.body.classList.toggle('dark');try{localStorage.setItem('robot-theme',dark?'dark':'light')}catch{}$('#theme').textContent=dark?'☀':'☾'};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#dialog').open){e.preventDefault();$('#search').focus()}});
render();if(params.has('article'))openArticle(params.get('article'));

const edition=document.querySelector('.edition b');if(edition&&window.ROBOT_NEWS_UPDATED_AT)edition.textContent=new Date(window.ROBOT_NEWS_UPDATED_AT).toLocaleDateString('th-TH',{day:'numeric',month:'long',year:'numeric'});
